"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  parseContacts,
  validateImportRows,
  type ImportRow,
} from "@/lib/imports";
import { importContacts } from "@/lib/actions";
import { Feedback, useUnsavedChanges } from "@/components/forms";
import { RoleChips } from "./RoleChips";
import type { ActionResult } from "@/lib/errors";
import { useSuccessNotification } from "@/components/notifications";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { Inbox, Upload } from "lucide-react";
import { PremiumLock } from "@/components/premium-lock";
import styles from "./contacts.module.css";
const PREVIEW_SIZE = 5;
export function ImportContacts({
  existingEmails,
  roles,
}: {
  existingEmails: string[];
  roles: string[];
}) {
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const [text, setText] = useState("");
  const [rawRows, setRows] = useState<ImportRow[]>([]);
  const rows = rawRows;
  const [previewPage, setPreviewPage] = useState(1);
  const [role, setRole] = useState("");
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const [reading, setReading] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [filename, setFilename] = useState("");
  const [fileSize, setFileSize] = useState(0);
  const [fileError, setFileError] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const busy = pending || reading;
  const validCount = rows.filter((r) => r.state === "valid").length;
  const duplicateCount = rows.filter((r) => r.state === "duplicate").length;
  const invalidCount = rows.filter((r) => r.state === "invalid").length;
  const router = useRouter();
  const notifySuccess = useSuccessNotification();
  useUnsavedChanges(!!text && !result?.ok);
  function preview(value: string) {
    if (!access.features.csvImport) return;
    try {
      if (!value.trim())
        throw new Error(
          "Your file or list is empty. Add contacts and try again.",
        );
      setPreviewPage(1);
      const parsed = parseContacts(value, existingEmails, role);
      if (!parsed.length)
        throw new Error(
          "No contact rows found. Add rows below the email header.",
        );
      setRows(parsed);
      setResult(undefined);
    } catch (e) {
      setRows([]);
      setResult({
        ok: false,
        message: e instanceof Error ? e.message : "Check your list.",
      });
    }
  }
  async function upload(files: File[]) {
    if (!access.features.csvImport || busy || !files.length) return;
    setRows([]);
    setText("");
    setFilename("");
    setResult(undefined);
    setFileError(false);
    const file = files[0];
    setFilename(file.name);
    if (files.length !== 1 || !/\.csv$/i.test(file.name)) {
      setFileError(true);
      setResult({
        ok: false,
        message:
          "Choose one CSV file (.csv). Download the sample for the correct format.",
      });
      return;
    }
    if (file.size > 1024 * 1024) {
      setFileError(true);
      setResult({ ok: false, message: "Choose a CSV up to 1 MB." });
      return;
    }
    setReading(true);
    try {
      const value = await file.text();
      setFileSize(file.size);
      setText(value);
      preview(value);
    } catch {
      setResult({
        ok: false,
        message:
          "Could not read this file. Choose the CSV again or paste your list below.",
      });
    } finally {
      setReading(false);
    }
  }
  function change(
    index: number,
    field: "name" | "email" | "company" | "jobRole",
    value: string,
  ) {
    setRows(
      validateImportRows(
        rows.map((r, i) => ({
          ...r,
          error: undefined,
          ...(i === index ? { [field]: value } : {}),
        })),
        existingEmails,
      ),
    );
    setResult(undefined);
  }
  function bulk(value: string) {
    setRole(value);
    setResult((current) => (current?.ok ? undefined : current));
    setRows(
      validateImportRows(
        rows.map((r) => ({ ...r, jobRole: value, error: undefined })),
        existingEmails,
      ),
    );
  }
  const heading = (
    <header className="flex items-start gap-3.5">
      <span className="workspace-icon-tile grid size-10 shrink-0 place-items-center rounded-xl bg-[var(--appearance-wash,var(--color-importcontacts-detail-1))] text-[var(--contacts-purple)]">
        <Inbox aria-hidden="true" size={20} />
      </span>
      <div className="min-w-0 flex-1">
        <h2
          id="contact-import-heading"
          className="text-[19px] font-extrabold tracking-[-.025em]"
        >
          Import contacts
        </h2>
        <p className="mt-1 text-sm text-[var(--contacts-muted)] workspace-mono:text-[12px] workspace-mono:leading-[1.6]">
          Bring in a whole list at once with a CSV file.
        </p>
      </div>
    </header>
  );
  if (!access.features.csvImport)
    return (
      <section
        aria-labelledby="contact-import-heading"
        className="workspace-mono:p-5.5 workspace-mono:rounded-[12px] workspace-mono:shadow-none workspace-mono:transform-none workspace-mono:backdrop-blur-none hover-card min-w-0 space-y-5 rounded-[var(--appearance-radius,24px)] border border-[var(--contacts-border)] bg-[var(--contacts-surface)] p-5 backdrop-blur-sm sm:p-[26px]"
      >
        {heading}
        <button
          type="button"
          aria-label="Choose a CSV file · Premium required"
          disabled={access.reasons.csvImport !== "UPGRADE_REQUIRED"}
          className="flex min-h-11 w-full cursor-pointer items-center gap-3 rounded-[var(--appearance-radius,14px)] border border-[var(--contacts-strong)] bg-[var(--contacts-inset)] px-4 py-3 text-left text-sm workspace-mono:rounded-[var(--appearance-control-radius)]"
          onClick={(event) =>
            upgrade({ feature: "csv", trigger: event.currentTarget })
          }
        >
          <span className="workspace-icon-tile grid size-10 shrink-0 place-items-center rounded-[var(--appearance-radius,12px)] bg-[var(--appearance-wash,var(--color-importcontacts-detail-1))] text-[var(--contacts-purple)]">
            <Upload size={20} aria-hidden="true" />
          </span>
          Choose a CSV file
        </button>
        <fieldset
          className="min-w-0"
          disabled={access.reasons.csvImport !== "UPGRADE_REQUIRED"}
        >
          <PremiumLock
            feature="CSV import"
            upgradeFeature="csv"
            variant="notice"
            description="Import up to 1,000 contacts from a CSV file, up to 1 MB."
          />
        </fieldset>
      </section>
    );
  return (
    <section
      className={`workspace-mono:p-5.5 workspace-mono:rounded-[12px] workspace-mono:shadow-none workspace-mono:transform-none workspace-mono:backdrop-blur-none ${styles.import} hover-card min-w-0 space-y-5 rounded-[var(--appearance-radius,24px)] border border-[var(--contacts-border)] bg-[var(--contacts-surface)] p-[26px] backdrop-blur-sm`}
      aria-labelledby="contact-import-heading"
    >
      {heading}
      <label
        className={`flex cursor-pointer items-center gap-3.5 rounded-[var(--appearance-radius,16px)] border-[1.5px] border-dashed p-[18px] focus-within:outline-2 focus-within:outline-offset-3 focus-within:outline-[var(--contacts-pink)] ${dragging ? "border-[var(--contacts-purple)] bg-[var(--appearance-wash,var(--color-importcontacts-detail-2))]" : "border-[var(--contacts-strong)] hover:bg-[var(--appearance-wash,var(--color-importcontacts-detail-2))]"} ${busy ? "pointer-events-none opacity-60" : ""}`}
        onDragOver={(e) => {
          e.preventDefault();
          if (!busy) setDragging(true);
        }}
        onDragLeave={(e) => {
          if (
            !(e.relatedTarget instanceof Node) ||
            !e.currentTarget.contains(e.relatedTarget)
          )
            setDragging(false);
        }}
        onDrop={(e) => {
          e.preventDefault();
          setDragging(false);
          void upload(Array.from(e.dataTransfer.files));
        }}
      >
        <span className="workspace-icon-tile grid size-10 shrink-0 place-items-center rounded-xl bg-[var(--appearance-wash,var(--color-importcontacts-detail-1))] text-[var(--contacts-purple)]">
          <Upload aria-hidden="true" size={20} />
        </span>
        <span className="min-w-0">
          <span className="block truncate font-bold">
            {filename || "Upload CSV"}
          </span>
          <span
            id="csv-upload-help"
            role="status"
            className={`mt-1 block text-[12.5px] ${fileError ? "text-[var(--contacts-red)]" : "text-[var(--contacts-muted)]"}`}
          >
            {fileError
              ? "Must be a CSV up to 1 MB"
              : reading
                ? "Reading CSV…"
                : filename
                  ? `${Math.round(fileSize / 1024)} KB · Ready to import`
                  : "Click to select a CSV · Up to 1 MB / 1,000 rows per import"}
          </span>
        </span>
        <input
          ref={fileInput}
          className="sr-only"
          aria-label="CSV file"
          aria-describedby="csv-upload-help"
          aria-invalid={fileError}
          type="file"
          name="csv"
          accept=".csv,text/csv"
          disabled={busy}
          onChange={(e) => {
            const files = Array.from(e.target.files ?? []);
            e.target.value = "";
            void upload(files);
          }}
        />
      </label>
      <details className="space-y-4">
        <summary className="cursor-pointer text-sm font-semibold text-[var(--contacts-purple)]">
          CSV format and paste options
        </summary>
        <ol className="list-decimal space-y-2 pl-5 text-sm text-body">
          <li>
            <a
              href="/sample-contacts.csv"
              download
              className="text-link underline underline-offset-4"
            >
              Download sample CSV
            </a>
            .
          </li>
          <li>
            Fill in the columns with your contacts, keeping the header row.
          </li>
          <li>Upload your CSV using the area below.</li>
          <li>Review the preview and correct any invalid rows.</li>
          <li>Confirm the import to save your contacts.</li>
        </ol>
        <div className="space-y-3">
          <h3 className="text-sm font-semibold">CSV columns</h3>
          <p className="text-sm text-body">
            <code>email</code> is required. <code>name</code>,{" "}
            <code>company</code>, and <code>role</code> are optional columns.{" "}
            <code>jobRole</code> also works as a role header.
          </p>
          <p className="text-sm text-body">
            Missing names may be suggested from email addresses. Review those
            suggestions and fill in any missing names and roles before
            confirming. Use Bulk Job Role to assign a role to all rows.
          </p>
          <div
            className="overflow-x-auto rounded-sm border border-control-border focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            role="region"
            aria-label="Example CSV columns"
            tabIndex={0}
          >
            <table className="w-full text-sm">
              <caption className="sr-only">Example CSV contacts</caption>
              <thead>
                <tr>
                  {["email (required)", "name", "company", "role"].map(
                    (column) => (
                      <th key={column} scope="col">
                        {column}
                      </th>
                    ),
                  )}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td>[REDACTED_EMAIL]</td>
                  <td>Alex</td>
                  <td>Northstar</td>
                  <td>Engineer</td>
                </tr>
                <tr>
                  <td>[REDACTED_EMAIL]</td>
                  <td>Sam</td>
                  <td></td>
                  <td>Designer</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
        <label className="block text-sm">
          Or paste your list
          <Textarea
            name="list"
            value={text}
            rows={5}
            autoComplete="off"
            spellCheck={false}
            maxLength={1024 * 1024}
            disabled={busy}
            onChange={(e) => {
              setText(e.target.value);
              setFilename("");
              setFileError(false);
              setRows([]);
              setResult(undefined);
            }}
            placeholder="[REDACTED_EMAIL]; [REDACTED_EMAIL]…"
          />
        </label>
        <p className="text-xs text-body">
          Paste emails separated by commas, semicolons, or newlines, or paste
          CSV with an email header.
        </p>
        <label className="block text-sm">
          Bulk Job Role
          <Input
            name="bulkRole"
            value={role}
            autoComplete="off"
            maxLength={160}
            disabled={busy}
            onChange={(e) => bulk(e.target.value)}
          />
        </label>
        <RoleChips roles={roles} value={role} onChoose={bulk} disabled={busy} />
        <Button
          variant="outline"
          disabled={busy || !text.trim()}
          onClick={() => preview(text)}
        >
          Preview Import
        </Button>
      </details>
      {rows.length > 0 && (
        <>
          <h3 className="text-sm font-semibold">Review your import</h3>
          <p className="text-sm" aria-live="polite">
            {validCount} valid · {duplicateCount} duplicate · {invalidCount}{" "}
            invalid
          </p>
          <p className="text-sm text-body">
            Duplicates already in your contacts or repeated in this list will be
            skipped.{" "}
            {invalidCount > 0
              ? "Correct all invalid rows before confirming the import."
              : validCount === 0
                ? "There are no new valid contacts to import."
                : "Your valid contacts are ready to import."}
          </p>
          <p className="text-xs text-body">
            Showing rows {(previewPage - 1) * PREVIEW_SIZE + 1}–
            {Math.min(previewPage * PREVIEW_SIZE, rows.length)} of {rows.length}
          </p>
          <div className="max-h-96 overflow-auto">
            <table className="w-full text-sm">
              <caption className="sr-only">Editable import preview</caption>
              <thead>
                <tr>
                  {[
                    "CSV row",
                    "Email",
                    "Name",
                    "Company (optional)",
                    "Job Role",
                    "Result",
                  ].map((v) => (
                    <th key={v} scope="col">
                      {v}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows
                  .slice(
                    (previewPage - 1) * PREVIEW_SIZE,
                    previewPage * PREVIEW_SIZE,
                  )
                  .map((r, i) => (
                    <tr key={r.row}>
                      <td>{r.row}</td>
                      {(["email", "name", "company", "jobRole"] as const).map(
                        (field) => (
                          <td key={field}>
                            <Input
                              className="min-w-40"
                              aria-label={`Row ${r.row} ${field}`}
                              name={field}
                              aria-describedby={
                                r.error ? `import-error-${r.row}` : undefined
                              }
                              value={r[field]}
                              autoComplete="off"
                              disabled={busy}
                              onChange={(e) =>
                                change(
                                  (previewPage - 1) * PREVIEW_SIZE + i,
                                  field,
                                  e.target.value,
                                )
                              }
                            />
                          </td>
                        ),
                      )}
                      <td className="min-w-48">
                        <p className="font-medium">
                          {r.state === "valid"
                            ? "Valid"
                            : r.state === "duplicate"
                              ? "Duplicate (skipped)"
                              : "Invalid"}
                        </p>
                        {r.error && (
                          <p
                            className="mt-1 text-[12.5px] text-[var(--contacts-red)]"
                            id={`import-error-${r.row}`}
                          >
                            {r.error}
                          </p>
                        )}
                      </td>
                    </tr>
                  ))}
              </tbody>
            </table>
          </div>
          {rows.length > PREVIEW_SIZE && (
            <div className="flex flex-wrap items-center gap-3">
              <Button
                variant="outline"
                disabled={busy || previewPage === 1}
                onClick={() => setPreviewPage(previewPage - 1)}
              >
                Previous Rows
              </Button>
              <span className="text-xs">
                Page {previewPage} of {Math.ceil(rows.length / PREVIEW_SIZE)}
              </span>
              <Button
                variant="outline"
                disabled={busy || previewPage * PREVIEW_SIZE >= rows.length}
                onClick={() => setPreviewPage(previewPage + 1)}
              >
                Next Rows
              </Button>
            </div>
          )}
          <Button
            disabled={busy || invalidCount > 0 || validCount === 0}
            onClick={() =>
              start(async () => {
                setResult(undefined);
                const submittedRows = rows.filter(
                  (row) => row.state !== "duplicate",
                );
                const r = await importContacts(submittedRows);
                if (!r.ok && r.fieldErrors) {
                  const errors = new Map<number, string>();
                  for (const [field, message] of Object.entries(
                    r.fieldErrors,
                  )) {
                    const match = /^rows\.(\d+)\.jobRole$/.exec(field);
                    const row = match
                      ? submittedRows[Number(match[1])]
                      : undefined;
                    if (row) errors.set(row.row, message);
                  }
                  if (errors.size) {
                    setRows((current) =>
                      current.map((row) =>
                        errors.has(row.row)
                          ? {
                              ...row,
                              state: "invalid",
                              error: errors.get(row.row),
                            }
                          : row,
                      ),
                    );
                    setPreviewPage(
                      Math.floor(
                        rows.findIndex((row) => errors.has(row.row)) /
                          PREVIEW_SIZE,
                      ) + 1,
                    );
                  }
                }
                setResult(r);
                if (r.ok) {
                  notifySuccess(
                    filename
                      ? "CSV imported successfully."
                      : "Contacts imported successfully.",
                  );
                  setText("");
                  setRows([]);
                  setFilename("");
                  router.refresh();
                }
              })
            }
            className={`${styles.primary} button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none inline-flex items-center justify-center gap-2 min-h-11.5 py-3 px-6 rounded-full [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] text-[14px] font-bold shadow-none`}
          >
            {pending ? "Importing…" : "Confirm import"}
          </Button>
        </>
      )}
      {result && (
        <Feedback result={result} successConfirmation planLabel="Premium" />
      )}
    </section>
  );
}
